#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "doitgen.h"

/* Tunable blocking factor for the inner p-dimension in kernel_doitgen.
 *
 * This controls how many consecutive entries of the p-dimension are processed
 * together when accumulating into `sum`.  It can be overridden at compile time
 * with e.g.:
 *
 *   gcc -DDOITGEN_TILE_P=128 ...
 *
 * On most modern x64 CPUs, values in the range [32, 256] work well.
 */
#ifndef DOITGEN_TILE_P
# define DOITGEN_TILE_P 64
#endif

#if DOITGEN_TILE_P <= 0
# error "DOITGEN_TILE_P must be a positive integer"
#endif


/* Array initialization. */
static
void init_array(int nr, int nq, int np,
		DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np))
{
  int i, j, k;

  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++)
      for (k = 0; k < np; k++)
	A[i][j][k] = (DATA_TYPE) ((i*j + k)%np) / np;
  for (i = 0; i < np; i++)
    for (j = 0; j < np; j++)
      C4[i][j] = (DATA_TYPE) (i*j % np) / np;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int nr, int nq, int np,
		 DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np))
{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++)
      for (k = 0; k < np; k++) {
	if ((i*nq*np+j*np+k) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimized version:
 *   - Reorders the inner loops to improve data locality.
 *   - Uses a single initialization of `sum` per (r, q) pair.
 *   - Traverses A and C4 in their natural contiguous (row-major) order.
 *   - Applies optional tiling on the p-dimension, controlled by
 *     DOITGEN_TILE_P, to keep working sets in L1/L2 cache.
 *
 * NOTE: For each (r, q, p), the sequence of floating-point operations
 *       (in terms of the summation over s) is preserved, so the result
 *       is bitwise identical to the original kernel.
 */
void kernel_doitgen[[gnu::flatten, gnu::noinline]](int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

  /* Local restrict-qualified aliases improve the compiler's ability to
   * optimize and vectorize the innermost loops by removing potential
   * aliasing between A, C4, and sum.
   *
   * We use the runtime sizes (nr, nq, np) so that these aliases match
   * the actual VLA shapes at call time.
   */
  DATA_TYPE (* restrict A_)[nq][np]  = (DATA_TYPE (* restrict)[nq][np]) A;
  DATA_TYPE (* restrict C4_)[np]     = (DATA_TYPE (* restrict)[np])     C4;
  DATA_TYPE * restrict sum_          = (DATA_TYPE * restrict)           sum;

#pragma scop
  for (r = 0; r < _PB_NR; r++) {
    for (q = 0; q < _PB_NQ; q++) {

      /* 1. Initialize the accumulation buffer once per (r, q).
       *    This is equivalent to the original code, which reset sum[p]
       *    at the start of each p-iteration.
       *    Here, for each p:
       *       original: sum[p] = 0; then for s: sum[p] += ...
       *       new:      sum[p] = 0 for all p; then for s: sum[p] += ...
       *    For any fixed p, the order of operations is identical.
       */
      for (p = 0; p < _PB_NP; p++) {
        sum_[p] = SCALAR_VAL(0.0);
      }

      /* 2. Compute:
       *       sum_[p] = sum_{s=0..NP-1} A_[r][q][s] * C4_[s][p]
       *
       *    Loop order is now:
       *       for s
       *         for p (with tiling)
       *
       *    This improves locality:
       *      - A_[r][q][s] is read sequentially along its innermost
       *        dimension (s).
       *      - C4_[s][p] is accessed with p as the innermost index and
       *        is therefore contiguous in memory (row-major layout).
       *      - sum_[p] is also updated contiguously in p.
       */
      for (s = 0; s < _PB_NP; s++) {
        /* Load once per s; reused for all p. */
        DATA_TYPE a_rqs = A_[r][q][s];

        /* Tile over p to keep sum_[] and the corresponding row of C4_
         * hot in cache, and to give the compiler a short, regular inner
         * loop to vectorize.
         */
        for (int p_outer = 0; p_outer < _PB_NP; p_outer += DOITGEN_TILE_P) {
          int p_limit = p_outer + DOITGEN_TILE_P;
          if (p_limit > _PB_NP)
            p_limit = _PB_NP;

          /* Tell GCC that there are no loop-carried dependencies between
           * different p iterations, which is true because each sum_[p] is
           * updated independently.
           */
#pragma GCC ivdep
          for (p = p_outer; p < p_limit; p++) {
            sum_[p] += a_rqs * C4_[s][p];
          }
        }
      }

      /* 3. Write back accumulated results.  This is unchanged in
       *    mathematical intent from the original code.
       */
      for (p = 0; p < _PB_NP; p++) {
        A_[r][q][p] = sum_[p];
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int nr = NR;
  int nq = NQ;
  int np = NP;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A,DATA_TYPE,NR,NQ,NP,nr,nq,np);
  POLYBENCH_1D_ARRAY_DECL(sum,DATA_TYPE,NP,np);
  POLYBENCH_2D_ARRAY_DECL(C4,DATA_TYPE,NP,NP,np,np);

  /* Initialize array(s). */
  init_array (nr, nq, np,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(C4));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_doitgen (nr, nq, np,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(C4),
		  POLYBENCH_ARRAY(sum));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(nr, nq, np,  POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(sum);
  POLYBENCH_FREE_ARRAY(C4);

  return 0;
}
