/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int nr, int nq, int np,
		 DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np))
{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++)
      for (k = 0; k < np; k++) {
	if ((i*nq*np+j*np+k) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
void kernel_doitgen[[gnu::flatten, gnu::noinline]](int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

  /* Create a restrict-qualified view of the temporary vector.
     This helps the compiler safely vectorize inner loops. */
  DATA_TYPE *restrict sum_local = sum;

#pragma scop
  /* For each (r, q) we compute:
       sum[p] = sum_{s} A[r][q][s] * C4[s][p]
     and then overwrite A[r][q][p] with sum[p].

     The original code iterated as:
       for p
         sum[p] = 0;
         for s
           sum[p] += A[r][q][s] * C4[s][p];

     We legally transform this to:
       for p
         sum[p] = 0;
       for s
         for p
           sum[p] += A[r][q][s] * C4[s][p];

     This preserves the per-element accumulation order in s
     (and therefore preserves floating-point semantics per element),
     but changes the memory-access pattern so that C4 is now
     traversed row-wise (contiguously in p), which greatly
     improves cache utilization and enables efficient SIMD. */
  for (r = 0; r < _PB_NR; r++)
    for (q = 0; q < _PB_NQ; q++)  {

      /* Pointer to the current (r,q) row of A.
         We reuse it for both reading the old values and
         writing back the transformed values. */
      DATA_TYPE *restrict A_rq = &A[r][q][0];

      /* Initialize the temporary accumulation vector once per (r,q). */
      for (p = 0; p < _PB_NP; p++)
        sum_local[p] = SCALAR_VAL(0.0);

      /* Main accumulation: walk A[r][q][s] linearly in s,
         and for each s, traverse C4[s][p] linearly in p.
         This gives contiguous access to both A (in s) and
         C4 (in p) and a tight, vectorizable inner loop. */
      for (s = 0; s < _PB_NP; s++) {
        const DATA_TYPE a_rqs = A_rq[s];
        const DATA_TYPE *restrict C4_row = &C4[s][0];

        /* Independent updates to sum_local[p]; safe to vectorize. */
#pragma GCC ivdep
        for (p = 0; p < _PB_NP; p++)
          sum_local[p] += a_rqs * C4_row[p];
      }

      /* Copy the result vector back into A[r][q][*]. */
#pragma GCC ivdep
      for (p = 0; p < _PB_NP; p++)
        A_rq[p] = sum_local[p];
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int nr = NR;
  int nq = NQ;
  int np = NP;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A,DATA_TYPE,NR,NQ,NP,nr,nq,np);
  POLYBENCH_1D_ARRAY_DECL(sum,DATA_TYPE,NP,np);
  POLYBENCH_2D_ARRAY_DECL(C4,DATA_TYPE,NP,NP,np,np);

  /* Initialize array(s). */
  init_array (nr, nq, np,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(C4));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_doitgen (nr, nq, np,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(C4),
		  POLYBENCH_ARRAY(sum));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(nr, nq, np,  POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(sum);
  POLYBENCH_FREE_ARRAY(C4);

  return 0;
}
