    }

  for (i = 0; i < np; i++) {
    /* Pointer to the contiguous row C4[i][:]. */
    DATA_TYPE *restrict C4_i = &C4_local[i][0];

    for (j = 0; j < np; j++)
      C4_i[j] = (DATA_TYPE) ((i * j) % np) / np;
  }
