  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++)
      for (k = 0; k < np; k++) {
	if ((i*nq*np+j*np+k) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
void kernel_doitgen [[gnu::flatten, gnu::noinline]](int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

  /* Local 'restrict' aliases to help the compiler with alias analysis.
     They are used exclusively inside the kernel body. */
  DATA_TYPE (*restrict A_local)[nq][np]      = A;
  const DATA_TYPE (*restrict C4_local)[np]   = C4;
  DATA_TYPE *restrict sum_local              = sum;

#pragma scop
  for (r = 0; r < _PB_NR; r++)
    for (q = 0; q < _PB_NQ; q++)  {

      /* Pointer to the contiguous slice A[r][q][:]. */
      DATA_TYPE *restrict A_row = &A_local[r][q][0];

#if DOITGEN_P_BLOCK_SIZE <= 0

      /* Initialize accumulation vector. This loop is simple and
         vectorizable. */
      #pragma GCC ivdep
      for (p = 0; p < _PB_NP; p++)
        sum_local[p] = SCALAR_VAL(0.0);

      /* Optimized loop nest:
         Original computation for fixed (r,q) was:
           for (p)
             sum[p] = 0;
             for (s)
               sum[p] += A[r][q][s] * C4[s][p];

         This version changes the inner order to (s, p):
           - A_row[s] is loaded once and reused across all p.
           - C4 is row-major, so C4[s][p] with p innermost is contiguous.
         For each p, the sequence of additions over s is preserved, so the
         floating-point evaluation order for each sum[p] is unchanged. */
      for (s = 0; s < _PB_NP; s++) {
        const DATA_TYPE a_val = A_row[s];
        const DATA_TYPE *restrict C4_row = &C4_local[s][0];

        #pragma GCC ivdep
        for (p = 0; p < _PB_NP; p++) {
          sum_local[p] += a_val * C4_row[p];
        }
      }

      /* Write back the accumulated result into A[r][q][:]. */
      #pragma GCC ivdep
      for (p = 0; p < _PB_NP; p++)
        A_row[p] = sum_local[p];

#else /* DOITGEN_P_BLOCK_SIZE > 0 : blocked variant for tuning */

      /* Initialize accumulation vector. */
      for (p = 0; p < _PB_NP; p++)
        sum_local[p] = SCALAR_VAL(0.0);

      /* Block over the p-dimension. This can help tune cache behavior
         when NP is large, at the cost of slightly more complex loops. */
      for (s = 0; s < _PB_NP; s++) {
        const DATA_TYPE a_val = A_row[s];
        const DATA_TYPE *restrict C4_row = &C4_local[s][0];

        for (int pb = 0; pb < _PB_NP; pb += DOITGEN_P_BLOCK_SIZE) {
          const int p_end = (pb + DOITGEN_P_BLOCK_SIZE < _PB_NP) ?
                            (pb + DOITGEN_P_BLOCK_SIZE) : _PB_NP;

          #pragma GCC ivdep
          for (p = pb; p < p_end; p++) {
            sum_local[p] += a_val * C4_row[p];
          }
        }
      }

      for (int pb = 0; pb < _PB_NP; pb += DOITGEN_P_BLOCK_SIZE) {
        const int p_end = (pb + DOITGEN_P_BLOCK_SIZE < _PB_NP) ?
                          (pb + DOITGEN_P_BLOCK_SIZE) : _PB_NP;

        #pragma GCC ivdep
        for (p = pb; p < p_end; p++)
          A_row[p] = sum_local[p];
      }

#endif /* DOITGEN_P_BLOCK_SIZE <= 0 */
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int nr = NR;
  int nq = NQ;
  int np = NP;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A,DATA_TYPE,NR,NQ,NP,nr,nq,np);
  POLYBENCH_1D_ARRAY_DECL(sum,DATA_TYPE,NP,np);
  POLYBENCH_2D_ARRAY_DECL(C4,DATA_TYPE,NP,NP,np,np);

  /* Initialize array(s). */
  init_array (nr, nq, np,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(C4));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_doitgen (nr, nq, np,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(C4),
		  POLYBENCH_ARRAY(sum));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(nr, nq, np,  POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(sum);
  POLYBENCH_FREE_ARRAY(C4);

  return 0;
}
