     sum[p] = Σ_s A[r][q][s] * C4[s][p];

   The optimized version below keeps the same mathematical result but
   reorganizes the inner loops to improve memory locality:

   - We initialize the whole sum[] vector once per (r,q).
   - We iterate over s in the outer inner loop and p in the innermost loop:
       for (s)
         for (p)
           sum[p] += A[r][q][s] * C4[s][p];
   - This allows us to traverse each row of C4 (C4[s][p]) contiguously in p,
     which is cache- and vectorization-friendly, instead of traversing C4
     column-wise as in the original code.
   - We then copy the resulting sum[] back into A[r][q][:].

   Local restrict-qualified pointers are introduced to give the compiler
   stronger aliasing guarantees without changing the externally visible API.
*/
void kernel_doitgen [[gnu::flatten, gnu::noinline]] (int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

  /* Use local restrict-qualified views of the input arrays.
     PolyBench allocators guarantee that these arrays do not overlap. */
  DATA_TYPE (*restrict A_)[NQ][NP] =
    (DATA_TYPE (*restrict)[NQ][NP])A;
  const DATA_TYPE (*restrict C4_)[NP] =
    (const DATA_TYPE (*restrict)[NP])C4;
  DATA_TYPE *restrict sum_ =
    (DATA_TYPE *restrict)sum;

#pragma scop
  for (r = 0; r < _PB_NR; r++) {

    /* Pointer to the 2D slice A[r][*][*] */
    DATA_TYPE (*restrict A_r)[NP] = A_[r];

    for (q = 0; q < _PB_NQ; q++) {

      /* Pointer to the 1D vector A[r][q][*] */
      DATA_TYPE *restrict a_vec = A_r[q];

      /* Initialize accumulation vector for this (r, q) pair. */
      for (p = 0; p < _PB_NP; p++)
        sum_[p] = SCALAR_VAL(0.0);

      /* Compute:
           sum[p] = Σ_s A[r][q][s] * C4[s][p]
         with improved locality for C4 by traversing rows contiguously. */
      for (s = 0; s < _PB_NP; s++) {
        const DATA_TYPE a_val = a_vec[s];
        const DATA_TYPE *restrict C4_row = C4_[s];

        /* No loop-carried dependencies across p; safe to vectorize. */
